class NamedOutputContractV1:
    math_spec_id: str
    schema_id: str
    schema_version: str
    output_name: str
    output_type: str
    output_shape: str
    unit: str
    basis: str
    domain: str
    precision: str
    rounding: str
    nullable: bool
    optional: bool
    members: tuple[NamedOutputMemberV1, ...]

    def __post_init__(self) -> None:
        if (
            self.schema_id != f"{self.math_spec_id}::OUTPUT"
            or self.schema_version != "ST12B_OUTPUT_V3_4"
            or not self.output_name
            or len({member.name for member in self.members}) != len(self.members)
            or self.nullable
            or self.optional
        ):
            raise ContractValidationError(
                ReasonCode.OUTPUT_SCHEMA_MISMATCH,
                "named output schema identity, members, or nullability is invalid",
            )


@dataclass(frozen=True, slots=True)
class FormulaRepositoryDispositionV1:
    math_spec_id: str
