def _st12b_shape(type_name: str) -> str:
    lowered = type_name.casefold()
    if "matrix" in lowered:
        return "matrix"
    if "list" in lowered or "vector" in lowered or "sequence" in lowered:
        return "vector"
    if "mapping" in lowered or "record" in lowered or "grammar" in lowered:
        return "object"
    return "scalar"


def _st12b_io_contract(requirement: FrozenFormulaRequirementV1) -> MathIOContractV1:
    typed = requirement.raw["typed_inputs"]
    if not isinstance(typed, tuple):
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT, "typed input ledger must be immutable"
        )
    inputs = tuple(
        TypedDataContractFieldV1(
            name=str(row["name"]),
            type_name=str(row["type"]),
            shape=_st12b_shape(str(row["type"])),
            unit=str(row["unit_or_basis"]),
            basis=str(row["domain"]),
        )
        for row in typed
        if isinstance(row, Mapping)
    )
    output = FROZEN_NAMED_OUTPUT_CONTRACTS[requirement.math_spec_id]
    return MathIOContractV1(
        math_id=requirement.math_spec_id,
        certified_name=requirement.name,
        inputs=inputs,
        outputs=(
            TypedDataContractFieldV1(
                name=output.output_name,
                type_name=output.output_type,
                shape=output.output_shape,
                unit=output.unit,
                basis=output.basis,
            ),
        ),
    )


_ST12B_MATH_IO_ROWS = tuple(
    _st12b_io_contract(requirement)
    for requirement in FROZEN_FORMULA_REQUIREMENTS.values()
)
MATH_IO_CONTRACTS = MappingProxyType(
    {row.math_id: row for row in _ST12B_MATH_IO_ROWS}
)


