def _validate_named_output_value(
    value: object,
    type_name: str,
    *,
    field_name: str,
) -> None:
    if value is None:
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            f"{field_name} is not nullable",
        )
    if type_name == "Decimal string":
        valid = isinstance(value, Decimal) and value.is_finite()
    elif type_name == "float64":
        valid = (
            isinstance(value, float)
            and not isinstance(value, bool)
            and math.isfinite(value)
        )
    elif type_name == "int":
        valid = isinstance(value, int) and not isinstance(value, bool)
    elif type_name == "bool":
        valid = type(value) is bool
    elif type_name in {"enum", "str"}:
        valid = isinstance(value, str) and bool(value)
    elif type_name == "record":
        valid = isinstance(value, Mapping)
    elif type_name.startswith("list["):
        valid = isinstance(value, list | tuple)
        if valid:
            element_type = type_name[5:-1]
            for index, item in enumerate(value):
                _validate_named_output_value(
                    item,
                    element_type,
                    field_name=f"{field_name}[{index}]",
                )
    elif type_name == "mapping[str,float64]":
        valid = isinstance(value, Mapping) and all(
            isinstance(key, str)
            and bool(key)
            and isinstance(item, float)
            and math.isfinite(item)
            for key, item in value.items()
        )
    elif type_name == "mapping[str,str]":
        valid = isinstance(value, Mapping) and all(
            isinstance(key, str)
            and bool(key)
            and isinstance(item, str)
            and bool(item)
            for key, item in value.items()
        )
    else:
        valid = False
    if not valid:
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            f"{field_name} does not satisfy frozen type {type_name}",
        )


def validate_formula_output_v34(math_spec_id: str, value: object) -> None:
    """Validate the native internal result before receipt serialization."""

    try:
        contract = FROZEN_NAMED_OUTPUT_CONTRACTS[math_spec_id]
    except KeyError as exc:
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            f"unknown frozen output schema: {math_spec_id}",
        ) from exc
    if contract.output_type != "record":
        _validate_named_output_value(
            value, contract.output_type, field_name=contract.output_name
        )
        return
    if not isinstance(value, Mapping):
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            f"{contract.output_name} must be a record",
        )
    expected_names = tuple(member.name for member in contract.members)
    if tuple(value) != expected_names:
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            f"{contract.output_name} member identity/order differs",
        )
    for member in contract.members:
        _validate_named_output_value(
            value[member.name],
            member.type_name,
            field_name=f"{contract.output_name}.{member.name}",
        )


def validate_current_formula_output(math_spec_id: str, value: object) -> None:
    """Validate predecessor outputs unchanged and the additive D scalar output."""

    if math_spec_id != "MATH-39":
        validate_formula_output_v34(math_spec_id, value)
        return
    if (
        not isinstance(value, Decimal)
        or isinstance(value, bool)
        or not value.is_finite()
        or value < 0
    ):
        raise ContractValidationError(
            ReasonCode.OUTPUT_SCHEMA_MISMATCH,
            "MATH-39 queue_ahead_estimate must be a finite nonnegative Decimal",
        )


if (
    len(FROZEN_FORMULA_REQUIREMENTS) != 30
    or len(FROZEN_FORMULA_INPUT_CONTRACTS) != 30
    or len(FROZEN_NAMED_OUTPUT_CONTRACTS) != 30
    or len(FROZEN_FORMULA_REPOSITORY_DISPOSITIONS) != 30
    or len(MATH_IO_CONTRACTS) != 30
    or sum(len(row.members) for row in FROZEN_NAMED_OUTPUT_CONTRACTS.values())
    != 130
):
    raise ContractValidationError(
        ReasonCode.INVALID_CONTRACT,
        "v3.4 requires 30 formulas, 30 schemas, and exactly 130 record members",
    )
